import { Component, Method, Prop } from "@stencil/core";
import { loadTimeZones } from "./load-time-zones";

/**
 * @since 2.0
 * @status stable
 */

@Component({
	tag: "hbr-format-date",
	shadow: true,
})
export class FormatDate {
	/** The date/time to format. If not set, the current date and time will be used. */
	@Prop() date: Date | string = new Date();

	/** The locale to use when formatting the date/time. */
	@Prop() locale: string;

	/** The format for displaying the weekday. */
	@Prop() weekday: "narrow" | "short" | "long";

	/** The format for displaying the era. */
	@Prop() era: "narrow" | "short" | "long";

	/** The format for displaying the year. */
	@Prop() year: "numeric" | "2-digit";

	/** The format for displaying the month. */
	@Prop() month: "numeric" | "2-digit" | "narrow" | "short" | "long";

	/** The format for displaying the day. */
	@Prop() day: "numeric" | "2-digit";

	/** The format for displaying the hour. */
	@Prop() hour: "numeric" | "2-digit";

	/** The format for displaying the minute. */
	@Prop() minute: "numeric" | "2-digit";

	/** The format for displaying the second. */
	@Prop() second: "numeric" | "2-digit";

	/** The format for displaying the time. */
	@Prop() timeZoneName: "short" | "long";

	/** The time zone to express the time in. */
	@Prop() timeZone: string;

	/** The time format can either be 12 or 24. The default "auto" value is dependent on the user locale time format value. Refer https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/DateTimeFormat/DateTimeFormat#hour12 */
	@Prop() hourFormat: "auto" | "12" | "24" = "auto";

	/** Deprecated, import timezones directly from utils */
	@Method()
	async getTimeZones() {
		return loadTimeZones();
	}

	render() {
		const date = new Date(this.date);
		let hour12 = {};
		if (this.hourFormat !== "auto") {
			hour12 = {
				hour12: this.hourFormat === "12" ? true : false,
			};
		}

		// Check for an invalid date
		if (Number.isNaN(date.getMilliseconds())) {
			return;
		}

		return new Intl.DateTimeFormat(this.locale, {
			weekday: this.weekday,
			era: this.era,
			year: this.year,
			month: this.month,
			day: this.day,
			hour: this.hour,
			minute: this.minute,
			second: this.second,
			timeZoneName: this.timeZoneName,
			timeZone: this.timeZone,
			...hour12,
		}).format(date);
	}
}
