type TimeZonesModule = {
	default: unknown;
};

type ImportTimeZones = () => Promise<TimeZonesModule>;

const importTimeZones = () => import("../../../utils/timeZones");

export function createTimeZonesLoader(
	importer: ImportTimeZones = importTimeZones,
) {
	let timeZonesPromise: Promise<unknown> | undefined;

	return async () => {
		if (!timeZonesPromise) {
			timeZonesPromise = importer().then(({ default: timeZones }) => timeZones);
		}

		try {
			return await timeZonesPromise;
		} catch (error) {
			timeZonesPromise = undefined;
			throw error;
		}
	};
}

export const loadTimeZones = createTimeZonesLoader();
